#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ArrayInitialValue {
    Integer(i32),
    Text,
}
#[derive(Debug, Clone)]
pub struct Instruction {
    pub array_default: Option<ArrayInitialValue>,
    pub opcode: Opcode,
    pub integer: i32,
    pub text: Option<String>,
    pub long: i64,
}
#[derive(Debug)]
pub struct Script {
    pub id: ScriptId,
    pub name: String,
    /// Integer, object/string and long locals and arguments.
    pub locals: [usize; 3],
    pub arguments: [usize; 3],
    pub instructions: Vec<Instruction>,
    pub switches: Vec<BTreeMap<i32, i32>>,
}

